+    @Override
+    protected GeometryFieldScript.Factory singleValueScript() {
+        return factory(s -> s.emit("POINT(-1 1)"));
+    }
+
+    @Override
+    protected GeometryFieldScript.Factory multipleValuesScript() {
+        return factory(s -> {
+            s.emit("POINT(-1 1)");
+            s.emit("POINT(-2 2)");
+        });
+    }
